// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2012, "8-9", [{"author":"И. Иткин и С. Переверзева","question":"В какой паре слова не связаны между собой по смыслу так, как в остальных?","choices":["<em>эгоист</em> — <em>эгоизм</em>","<em>пессимист</em> — <em>пессимизм</em>","<em>органист</em> — <em>организм</em>","<em>импрессионист</em> — <em>импрессионизм</em>","во всех этих парах слова связаны между собой одинаково."],"key":"В","review":["Отношение между словами","Определи, чем человек из первого слова связан с понятием из второго. Например, пессимист склонен к пессимизму.","Эгоист, пессимист и импрессионист связаны с соответствующими взглядами или направлением. Органист играет на органе. «Организм» не называет его занятие или взгляды."]},{"author":"Б. Иомдин","question":"<em>Кам</em> (на удмуртском языке), <em>енэ-сий</em> (на древнененецком языке), <em>миси-зииби</em> (на языке индейцев оджибве), <em>юкон</em> (на языке индейцев гвичин) означает","choices":["высокая гора","большая река","густой лес","родной язык","велосипед."],"key":"Б","review":["Названия на разных языках","Произнеси названия и вспомни знакомые географические имена — Каму, Миссисипи и Юкон.","Все четыре названия относятся к большим рекам. В данных языках их названия связывали со значением «большая река»."]},{"author":"С. Переверзева","question":"Сколько слов в следующем списке имеет один и тот же корень: <em>огораживать</em>, <em>завораживать</em>, <em>облагораживать</em>, <em>обезображивать</em>, <em>обескураживать</em>?","choices":["два","три","четыре","пять","в этом списке нет слов с одним и тем же корнем."],"key":"Д","review":["Корни близких по виду слов","Подбери к каждому глаголу родственное слово, в котором корень хорошо заметен.","Получаем «ограда», «ворожить», «благородный», «образ», «кураж». За похожими частями слов стоят разные корни."]},{"author":"И. Иткин","question":"В каком слове пропущена не та буква, что в остальных?","choices":["<em>перехо</em>...","<em>пешехо</em>...","<em>доброхо</em>...","<em>скорохо</em>...","во всех этих словах пропущена одна и та же буква."],"key":"В","review":["Конец сложного слова","Восстанови слова и сравни их последние части. У одного из них конец связан с желанием, а не с ходьбой.","Пишут «переход», «пешеход», «доброхот», «скороход». Только «доброхот» заканчивается на «т» и связан с корнем «хот-»."]},{"author":"Б. Иомдин","question":"Андрей разбил аквариум. Вова разбил витрину. Петя разбил палатку. Миша разбил машину. Кто из них не испортил вещь?","choices":["Андрей","Вова","Петя","Миша","все четверо испортили."],"key":"В","review":["Четыре значения действия","Представь, что означает «разбить» рядом с каждым дополнением. В одном случае речь о подготовке места для ночлега.","«Разбить палатку» значит поставить, развернуть её. Петя ничего не испортил. В других фразах глагол означает, что вещь повредили."]},{"author":"И. Иткин","question":"Многоточие — это знак препинания, который представляет собой","choices":["две точки","три точки","четыре точки","три или четыре точки","много точек."],"key":"Б","review":["Сколько точек в знаке","Вспомни, как на письме обозначают незаконченную мысль или паузу в конце фразы.","Многоточие состоит из трёх точек. Именно так этот знак выглядит в обычной записи."]},{"author":"Л. Фёдорова","question":"Что можно <em>принять</em>, <em>нести</em>, <em>передать</em>, <em>пробежать</em>, <em>выиграть</em>?","choices":["<em>сообщение</em>","<em>вахту</em>","<em>традицию</em>","<em>дистанцию</em>","<em>эстафету</em>."],"key":"Д","review":["Слово для пяти глаголов","Подставь к одному слову все пять глаголов. «Пробежать» сужает выбор до чего-то, связанного с бегом.","Эстафету можно принять и передать, нести как символ, пробежать и выиграть как соревнование. Она сочетается со всеми глаголами."]},{"author":"Е. Бикмаев","question":"Слово <em>антоним</em> можно охарактеризовать как","choices":["антоним к слову <em>синоним</em>","синоним к слову <em>синоним</em>","антоним к слову <em>омоним</em>","омоним к слову <em>антоним</em>","синоним к слову <em>омоним</em>."],"key":"А","review":["Термины со встречными смыслами","Вспомни, какие отношения между значениями называют синонимией и антонимией.","«Синоним» означает слово с близким значением, «антоним» — с противоположным. Как названия противоположных типов отношений они сами могут рассматриваться как антонимы."]},{"author":"Е. Муравенко","question":"В каком из данных предложений, взятых из произведений конца XVIII — начала XIX века, подчёркнутая форма множественного числа существительного соответствует современной литературной норме?","choices":["<em>Иногда, оставляя книгу, смотрел он на синее пространство Волги, на белые <u>парусы</u> судов и лодок</em>... (Н. М. Карамзин)","<em><u>Окны</u> во флигеле были загорожены деревянною решёткою</em>. (А. С. Пушкин)","<em>Мелькают замки, церкви, крестьянские <u>домы</u></em>. (В. А. Жуковский)","<em>Несколько троек, наполненных разбойниками, … приезжали в <u>сёлы</u></em>. (А. С. Пушкин)","<em>Пётр с тамошними купцами заключил <u>договоры</u>, между прочим о продаже табака</em>. (А. С. Пушкин)"],"key":"Д","review":["Множественное число в цитатах","Сопоставь подчеркнутые формы с теми, которые употребляют в современной литературной речи.","Сегодня говорят «паруса», «окна», «дома» и «сёла». Форма «договоры» из последней цитаты соответствует современной норме."]},{"author":"А. Панина","question":"Первоначально буквальный смысл слова <em>восхитить</em> был ‘схватить и унести ...’.","choices":["вверх","вниз","сюда","отсюда","в разные стороны."],"key":"А","review":["Древний смысл глагола","Сравни старую приставку «вос-» с той же частью слова «восходить». Что она говорит о направлении?","Приставка указывала на движение вверх. Старое «восхитить» буквально значило схватить и унести вверх."]},{"author":"А. Иткин","question":"Сколько дробей можно описать выражением <em>тысяча сто шестьдесят девятых</em>?","choices":["ни одной","одну","две","три","четыре."],"key":"Г","review":["Разные дроби из одной фразы","Раздели фразу после «тысяча», после «сто» и после «шестьдесят». До границы должны стоять целые числа, после неё — знаменатель.","Получаются три дроби: 1000/169, 1100/69 и 1160/9. Каждая из них читается с теми же словами при другой границе."]},{"author":"И. Рубанов","question":"<em>Свет отключился в два часа ночи. Электроснабжение не удалось восстановить и к утреннему ... .</em>","choices":["<em>часу пик</em>","<em>час пику</em>","<em>час пик</em>","<em>часу пика</em>","<em>час пику</em>."],"key":"А","review":["Падеж в выражении о часе","Поставь после «к утреннему» вопрос «чему?». В выражении «час пик» изменяется основное слово.","«К часу пик» сохраняет «пик» в прежней форме. Слово «час» получает окончание дательного падежа."]},{"author":"П. Аркадьев","question":"Какое из данных слов содержит приставку <em>обо-</em>?","choices":["<em>обоюдный</em>","<em>оборот</em>","<em>обогрев</em>","<em>оболочка</em>","<em>обочина</em>."],"key":"В","review":["Граница приставки","Сравни слова с другими формами соответствующего корня. Например, сопоставь «обогрев» с «грев» и «нагрев».","В «обогрев» выделяется приставка «обо-» и корень «-грев-». В других словах такое деление не выделяет «обо-»."]},{"author":"Б. Иомдин","question":"<em>Майор быстро с</em>_____<em>нтировался и двинулся в нужном ему направлении</em> (А. Азольский). Заполните пропуск.","choices":["<em>оре</em>","<em>ори</em>","<em>ооре</em>","<em>оорие</em>","<em>орие</em>."],"key":"Д","review":["Пропуск в слове о направлении","Сопоставь пропуск с буквами глагола «ориентироваться». В совершенной форме добавляется приставка «с-».","Пишут «сориентировался». Между начальной «с» и «нтировался» стоят буквы «орие»."]},{"author":"А. Пиперски","question":"Даны пары строк из поэмы М. Ю. Лермонтова «Мцыри». В каком примере рифмующиеся слова стоят в одном падеже?","choices":["<em>Про волю дикую степей,</em> / <em>Про лёгких, бешеных коней...</em>","<em>Она скользила меж камней,</em> / <em>Смеясь неловкости своей.</em>","<em>Моя кружилась голова;</em> / <em>Я стал влезать на дерева...</em>","<em>Ты видишь на груди моей</em> / <em>Следы глубокие когтей...</em>","<em>Всё это смутной чередой</em> / <em>Вдруг пробегало предо мной.</em>"],"key":"Д","review":["Падежи рифмующихся слов","Для каждой пары поставь вопросы к словам на конце строк. Рифма сама по себе не определяет падеж.","«Смутной чередой» и «предо мной» стоят в творительном падеже. В других парах рифмуются разные падежи."]},{"author":"Е. Литвин и А. Сомин","question":"Некогда в Италии бытовало поверье, что одна из психических болезней вызывается укусом паука, а вылечить её можно танцем. Как назывался этот танец?","choices":["<em>сарабанда</em>","<em>сальса</em>","<em>кадриль</em>","<em>тарантелла</em>","<em>сальтарелло</em>."],"key":"Г","review":["Танец старой Италии","Вспомни название большого паука и итальянский город Таранто. Одно название танца звучит похоже.","С поверьем о лечении укуса тарантула связывали тарантеллу. Оба названия соотносятся с Таранто."]},{"author":"И. Рубанов","question":"В одной статье в Интернете читаем: <em>Свою задачу мы видим в том, чтобы выпускать принципиально новые устройства небольшими, но постоянно усовершенствованными партиями.</em> А как правильно было бы закончить эту фразу?","choices":["постоянно усовершенствующими партиями","постоянно совершенствующими партиями","постоянно усовершенствуемыми партиями","постоянно совершенствуемыми партиями","постоянно усовершенствовавшимися партиями."],"key":"Г","review":["Причастие и повторение","Слово «постоянно» указывает на продолжающееся действие. Партии сами его не выполняют.","«Совершенствуемыми» — страдательное причастие от несовершенного «совершенствовать». Форма передаёт, что партии постоянно улучшают."]},{"author":"А. Пиперски","question":"Между какими согласными не может проходить граница корня и суффикса?","choices":["<em>дн</em>","<em>лн</em>","<em>нн</em>","<em>сн</em>","<em>тн.</em>"],"key":"Б","review":["Корень рядом с суффиксом","Подбери слово, в котором «-н-» добавляется к корню на одну из данных согласных. Смотри, не появляется ли мягкий знак.","Есть «холод-н-ый», «сон-н-ый», «вкус-н-ый», «ответ-н-ый». В словах вроде «боль-н-ой» перед суффиксом стоит мягкое «ль». Сочетание с твёрдым «л» не подходит."]},{"author":"А. и И. Иткины","question":"Выполняя домашнее задание, Миша составил пять пар слов. Учитель, однако, сказал, что одну пару Миша подобрал неправильно. Какую?","choices":["<em>считать — счёт</em>","<em>отсчитать — отсчёт</em>","<em>пересчитать — пересчёт</em>","<em>подсчитать — подсчёт</em>","<em>просчитать — просчёт</em>."],"key":"Д","review":["Смысл слова «просчёт»","Проверь, называет ли существительное действие соседнего глагола или что-то другое.","«Просчёт» — ошибка, обычно результат того, что просчитались. Остальные существительные связаны с действиями соответствующих глаголов."]},{"author":"М. Рубинштейн и А. Сомин","question":"Учитель попросил Федю привести четыре примера устойчивых выражений. Какой из приведённых Федей примеров учителю не придётся исправлять?","choices":["<em>Был да всплыл</em>.","<em>Хоть кол на голове чеши</em>.","<em>В душе не чаял</em>.","<em>В коем-то веке</em>.","Учителю придётся исправить все выражения (А)–(Г)."],"key":"Д","review":["Устойчивые обороты","Сравни выражения с тем, как они обычно звучат. Иногда ошибка состоит в замене всего одной буквы или в падеже.","Говорят «был да сплыл», «хоть кол на голове теши», «души не чаял», «в кои-то веки». Исправить нужно все четыре примера."]},{"author":"Е. Муравенко","question":"Даны обозначения действий и инструментов для их выполнения. В какой из пар соотношение между её членами не совсем такое, как в других парах?","choices":["<em>рубить — топор</em>","<em>резать — нож</em>","<em>стрелять — ружьё</em>","<em>чистить — щётка</em>","<em>копать — лопата</em>."],"key":"В","review":["Глагол и орудие","Поставь название орудия после глагола. В каком случае употребителен оборот с предлогом «из»?","Обычно «стрелять из ружья». Другие орудия ставят в творительном падеже: рубить топором, резать ножом, чистить щёткой, копать лопатой."]},{"author":"И. Иткин","question":"В стихотворении Г. Р. Державина «Колесница» упоминаются <em>ра_бруенные Буцефалы</em>. А как следует писать слово <em>ра_бруенный</em> в соответствии с современными орфографическими правилами?","choices":["через <em>з</em>","через <em>с</em>","через <em>зз</em>","через <em>сс</em>","через <em>зс</em>."],"key":"Г","review":["Две буквы у границы частей","Восстанови слово «сбруя». Его начальная согласная сохранится и после прибавления приставки.","Пишут «рас-сбруенный»: конечная «с» приставки «рас-» и начальная «с» слова «сбруя» дают две буквы «с» подряд."]},{"author":"И. Иткин","question":"У какого из этих слов основа в древности оканчивалась звуком <em>р</em>, впоследствии исчезнувшим?","choices":["<em>дом</em>","<em>друг</em>","<em>дуб</em>","<em>пест</em>","<em>ступа</em>."],"key":"В","review":["Согласный в старой основе","Поищи среди родственных слов такое, где за корнем стоит «р». Подсказку даёт название леса.","В ключе указан «дуб»: в «дубраве» видна основа «дубр-». Этимологические словари также фиксируют древнюю форму «дуб» без «р». Задание использует первую трактовку."]},{"author":"Е. Муравенко","question":"Какие из слов: <em>слово</em>, <em>дело</em>, <em>тело</em> — в древнерусском языке склонялись так же, как слово <em>чудо</em>, сохранившее и сейчас прежние особенности в склонении?","choices":["<em>слово</em> и <em>дело</em>","<em>слово</em> и <em>тело</em>","<em>дело</em> и <em>тело</em>","только <em>слово</em>","все три слова."],"key":"Б","review":["Древнее склонение","Вспомни формы «чудеса» и «чудес». У других существительных встречались похожие расширения основы.","«Словеса» и «телеса» сохраняют «-ес-». Слова «слово» и «тело» в древности склонялись по тому же типу, что «чудо»."]},{"author":"Е. Муравенко","question":"Какое слово образовано не тем способом, что остальные?","choices":["<em>новорождённый</em>","<em>вперёдсмотрящий</em>","<em>умалишённый</em>","<em>сейчас</em>","<em>сегодня</em>."],"key":"А","review":["Образование сложного слова","Проверь, получились ли слова из целого словосочетания. Сравни, например, «сейчас» и «сей час».","«Вперёдсмотрящий», «умалишённый», «сейчас» и «сегодня» возникли от слияния словосочетаний. В «новорождённый» первая часть «ново-» присоединяется при сложении основ."]},{"author":"А. Пиперски","question":"<em>Несгораемый</em>, <em>неиссякаемый</em>, <em>несмолкаемый</em>, … .","choices":["<em>незабываемый</em>","<em>неисчерпаемый</em>","<em>неувядаемый</em>","<em>несгибаемый</em>","<em>нескрываемый.</em>"],"key":"В","review":["Прилагательные на «-емый»","Сними «не-» и найди глагол исходного действия. У нескольких глаголов отсутствует прямой объект.","«Сгорать», «иссякать», «смолкать» и «увядать» здесь непереходные. «Неувядаемый» продолжает ряд прилагательных, внешне похожих на страдательные причастия."]},{"author":"К. Гилярова","question":"Какая профессия по-словенски называется <em>tajnik</em>?","choices":["полицейский","таможенник","банкир","секретарь","врач."],"key":"Г","review":["Профессия на словенском","Сопоставь «tajnik» с русскими словами «тайна» и «секрет». Какую должность называют от слова со значением «секрет»?","По-словенски «tajnik» означает «секретарь». В обоих языках название связано со словами о тайне."]},{"author":"Б. Иомдин","question":"Подавляющее большинство слов на <em>-итель</em> подчиняется некоторому общему правилу, исключений из которого очень мало. Одно из них <em>―</em> редкое слово <em>движитель</em> («<em>Он движитель систем планетных, // Малейших и больших ― равно нам неприметных</em>», <em>―</em> писал поэт А. Х. Востоков). Найдите ещё одно.","choices":["<em>делитель</em>","<em>множитель</em>","<em>наполнитель</em>","<em>нарушитель</em>","<em>служитель.</em>"],"key":"Б","review":["Ударение в словах на «-итель»","Произнеси «движитель» и проверь, остаётся ли ударение на том же месте относительно окончания в других словах.","Обычно ударение падает на «и»: «дели́тель», «наполни́тель», «наруши́тель», «служи́тель». Слова «дви́житель» и «мно́житель» выделяются ударением на корне."]},{"author":"М. Руссо","question":"Большинство астероидов движется вокруг Солнца против часовой стрелки. Одним из исключений является астероид, который называется...","choices":["<em>Диадема</em>","<em>Диалекта</em>","<em>Диоретса</em>","<em>Диабата</em>","<em>Диомея</em>."],"key":"В","review":["Имя астероида","Раз направление движения противоположно обычному, попробуй прочитать названия в противоположную сторону.","«Диоретса» при чтении справа налево превращается в «астероид». Это имя астероида с обратным направлением обращения."]},{"author":"С. Переверзева","question":"Даны глагольные формы языка хинди ― одного из государственных языков Индии ― и их переводы на русский язык:\n<em>bonā</em> ― сеять, <em>boyā</em> ― сеявший, <em>khodā</em> ― копавший, <em>khodī</em> ― копавшая,\n<em>khodnā</em> ― копать, <em>mānā</em> ― признававший, <em>pāyā</em> ― находивший,\n<em>roī</em> ― плакавшая.\nПереведите на хинди: <em>сеявшая, находить, плакавший, признавать.</em>\n(Примечание. Чёрточка над гласной обозначает долготу.)","choices":["boī, pānā, royā, mānnā","boyī, pānā, roā, mānā","boī, pānā, roā, mānnā","boyī, pāynā, royā, mānnā","boyī, pānnā, roā, mānā."],"key":"А","review":["Формы глаголов хинди","Выдели окончание инфинитива по «khodnā». В мужской форме после гласной ориентируйся на «boyā», в женской — на «roī».","Получаем «boī», «pānā», «royā», «mānnā». В последнем слове «n» есть в основе «mān-» и в конце инфинитива «-nā»."]}], {"year":2012,"grade":"8-9","tasksFile":"8-9.pdf","answersFile":"8-9-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2012.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
